            adj_s[s].add(b)
            adj_b[b].add(s)

    # Find connected components.
    seen_s = set()
    seen_b = set()
    components = []
    for s in students:
        if s in seen_s:
            continue
        # BFS over bipartite graph.
        comp_s = set()
        comp_b = set()
        stack = [("s", s)]
        seen_s.add(s)
