            kind, node = stack.pop()
            if kind == "s":
                comp_s.add(node)
                for b in adj_s[node]:
                    if b not in seen_b:
                        seen_b.add(b)
                        stack.append(("b", b))
            else:
                comp_b.add(node)
                for s2 in adj_b[node]:
                    if s2 not in seen_s:
                        seen_s.add(s2)
                        stack.append(("s", s2))
        components.append((sorted(comp_s), sorted(comp_b)))

