        if c > 0:
            adj_s[s].add(b)
            adj_b[b].add(s)

    # Find connected components.
    seen_s = set()
    seen_b = set()
    components = []
    for s in students:
        if s in seen_s:
            continue
        # BFS over bipartite graph.
        comp_s = set()
        comp_b = set()
        stack = [("s", s)]
        seen_s.add(s)
        while stack:
            kind, node = stack.pop()
            if kind == "s":
                comp_s.add(node)
                for b in adj_s[node]:
                    if b not in seen_b:
                        seen_b.add(b)
                        stack.append(("b", b))
            else:
                comp_b.add(node)
                for s2 in adj_b[node]:
