    forced.sort(key=lambda p: p[0])

    return {
        "floor": best_floor,
        "total": best_total,
        "count": count,
        "min_num": min_num,
        "max_num": max_num,
        "min_buyers": min_vec,
        "max_buyers": max_vec,
