            adj_s[s].add(b)
            adj_b[b].add(s)

    seen_s = set()
    seen_b = set()
    components = []
    for s in students:
        if s in seen_s:
            continue
        comp_s = set()
        comp_b = set()
        stack = [("s", s)]
        seen_s.add(s)
        while stack:
            kind, node = stack.pop()
            if kind == "s":
                comp_s.add(node)
                for b in adj_s[node]:
                    if b not in seen_b:
                        seen_b.add(b)
                        stack.append(("b", b))
            else:
                comp_b.add(node)
                for s2 in adj_b[node]:
                    if s2 not in seen_s:
                        seen_s.add(s2)
                        stack.append(("s", s2))
        components.append((sorted(comp_s), sorted(comp_b)))

    for comp_s, comp_b in components:
        if len(comp_s) != len(comp_b):
            return None

    covered_s = set()
    covered_b = set()
    for comp_s, comp_b in components:
        covered_s.update(comp_s)
        covered_b.update(comp_b)
    if covered_s != set(students) or covered_b != set(buyers):
        return None

    comp_matchings = []
    for comp_s, comp_b in components:
        matchings = []
        for perm in permutations(comp_b):
            if all(conf.get((s, b), 0) > 0 for s, b in zip(comp_s, perm)):
                matchings.append(list(zip(comp_s, perm)))
