        key = (student, buyer)
        if key not in best:
            best[key] = {}
        if source not in best[key] or strength > best[key][source]:
            best[key][source] = strength
    return {k: sum(v.values()) for k, v in best.items()}


def _solve(payload, left, right, conf):
    """Solve one drop scenario. Returns result dict or None."""
    students = payload["students"]
    buyers = payload["buyers"]
    n = len(students)

    adj_s = {s: set() for s in students}
    adj_b = {b: set() for b in buyers}
    for (s, b), c in conf.items():
        if c > 0:
            adj_s[s].add(b)
            adj_b[b].add(s)

    seen_s = set()
    seen_b = set()
    components = []
    for s in students:
        if s in seen_s:
            continue
        comp_s = set()
        comp_b = set()
        stack = [("s", s)]
        seen_s.add(s)
        while stack:
            kind, node = stack.pop()
            if kind == "s":
                comp_s.add(node)
                for b in adj_s[node]:
                    if b not in seen_b:
                        seen_b.add(b)
                        stack.append(("b", b))
            else:
                comp_b.add(node)
                for s2 in adj_b[node]:
                    if s2 not in seen_s:
