        stack = [("s", s)]
        seen_s.add(s)
        while stack:
            kind, node = stack.pop()
            if kind == "s":
                comp_s.add(node)
                for b in adj_s[node]:
                    if b not in seen_b:
                        seen_b.add(b)
                        stack.append(("b", b))
            else:
