        if num == max_num and (max_vec is None or vec < max_vec):
            max_vec = vec

    forced = []
    for s in students:
        bs = set()
        for matching in optimal:
            bs.add(dict(matching)[s])
        if len(bs) == 1:
            forced.append([s, bs.pop()])
    forced.sort(key=lambda p: p[0])

    return {
