        "total": best_total,
        "count": count,
        "min_num": min_num,
        "max_num": max_num,
        "min_buyers": min_vec,
        "max_buyers": max_vec,
        "forced": forced,
    }


def combine(payload, left, right):
    results = []
    for drop in payload["drop"]:
        conf = _build_evidence(payload, drop)
        result = _solve(payload, left, right, conf)
        results.append({"drop": drop, "result": result})
    return results
