        if num == max_num and (max_vec is None or vec < max_vec):
            max_vec = vec

    forced = []
    for s in students:
        bs = set()
        for matching in optimal:
            bs.add(dict(matching)[s])
        if len(bs) == 1:
            forced.append([s, bs.pop()])
    forced.sort(key=lambda p: p[0])

    return {
        "floor": best_floor,
        "total": best_total,
        "count": count,
        "min_num": min_num,
        "max_num": max_num,
        "min_buyers": min_vec,
        "max_buyers": max_vec,
        "forced": forced,
    }


